my_data = [
  "",
  "",
  "",
]
# Independent native value checks.
expected = [[], (0..255).to_a, (0..255).to_a.reverse]
case "BASE64"
when "HEX"
  expected = expected.map { |octets| octets.pack("C*").unpack1("H*") }
when "BASE64"
  expected = expected.map { |octets| [octets.pack("C*")].pack("m0") }
else
  raise "unchecked bytes representation"
end
raise "byte values or types changed" unless my_data.all? { |value| value.instance_of?(String) } && my_data == expected
